def magic_square_test(matrix):
    """
    Check if the given square matrix is a magic square.

    A magic square is a square matrix in which the sum of every row, 
    every column, and both main diagonals is the same.
    """
    if not matrix:
        return True

    n = len(matrix)
    sum_val = sum(matrix[0])

    # Check row sums
    for row in matrix:
        if sum(row) != sum_val:
            return False

    # Check column sums
    for i in range(n):
        if sum(row[i] for row in matrix) != sum_val:
            return False

    # Check main diagonal (top-left to bottom-right)
    if sum(matrix[i][i] for i in range(n)) != sum_val:
        return False

    # Check anti-diagonal (top-right to bottom-left)
    if sum(matrix[i][n - 1 - i] for i in range(n)) != sum_val:
        return False

