def is_samepatterns(elems, patterns):
    """
    Checks whether the first list follows the same pattern as the second list.
    Two lists follow the same pattern if there is a bijection between 
    the elements of the first list and the elements of the second list.
    """
    if len(elems) != len(patterns):
        return False

    map_forward = {}
    map_backward = {}

    for e, p in zip(elems, patterns):
        # Check forward mapping (e -> p)
        if e in map_forward:
            if map_forward[e] != p:
                return False
        else:
            map_forward[e] = p

        # Check backward mapping (p -> e) to ensure a bijection
        if p in map_backward:
            if map_backward[p] != e:
                return False
        else:
            map_backward[p] = e

